def solution(input_str: str) -> str:
    """
    Determines the winner of the matrix game.

    The game is equivalent to Nim where each cell value contributes to an XOR sum.
    If XOR sum is 0, the second player (Jeel) wins.
    Otherwise, the first player (Ashish) wins.
    """
    lines = input_str.strip().split('\n')
    idx = 0

    result = []

    if idx >= len(lines):
        return ''

    t = int(lines[idx])
    idx += 1

    for _ in range(t):
        if idx >= len(lines):
            break

        n, m = map(int, lines[idx].split())
        idx += 1

        xor_sum = 0
        for _ in range(n):
            if idx >= len(lines):
                break
            row = list(map(int, lines[idx].split()))
            idx += 1
            for val in row:
                xor_sum ^= val

        if xor_sum == 0:
            result.append("Jeel")
        else:
            result.append("Ashish")

    return '\n'.join(result)

