def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    roads = []
    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        roads.append((x, y, w, i + 1))

    # Check if s and t are already disconnected without removing any roads
    def bfs_check(start, blocked_edges):
        """BFS to check if start can reach t, avoiding blocked edges"""
        visited = {start}
        queue = [start]

        while queue:
            current = queue.pop(0)
            if current == t:
                return False  # s can reach t

            for x, y, w, idx in roads:
                if idx in blocked_edges:
                    continue
                if x == current:
                    if y not in visited:
                        visited.add(y)
                        queue.append(y)
                elif y == current:
                    if x not in visited:
                        visited.add(x)
                        queue.append(x)

        # If we're here, t was never reached from start
        # Check if t is in the final visited set
        # We need to track if we can actually reach t
        return True  # If t was never reached quotient from s, they're disconnected

    # Better BFS approach - check reachability to t
    def check_connectivity(start, blocked_edges):
        """Check if t is reachable from start, considering blocked edges"""
        visited = {start}
        queue = [start]

        while queue:
            current = queue.pop(0)

            for x, y, w, idx in roads:
                if idx in blocked_edges:
                    continue
                if x == current:
                    if y not in visited:
                        if y == t:
                            return True  # t is reachable
                        visited.add(y)
                        queue.append(y)
                elif y == current:
                    if x not in visited:
                        if x == t:
                            return True  # t is reachable
                        visited.add(x)
                        queue.append(x)

        # t was not reached
        return False

    # Already disconnected?
    already_disconnected = not check_connectivity(s, set())
    if already_disconnected:
        return "0\n0\n"

    best_cost = float('inf')
    best_roads = None

    # Case 0: Check single road removal
    for idx, (x, y, w, road_id) in enumerate(roads):
        if check_connectivity(s, {road_id}):
            continue  # This edge alone doesn't disconnect
        # Check cost
        cost = w
        if cost < best_cost:
            best_cost = cost
            best_roads = [road_id]

    # Case 1: Check two road removal if single isn't enough
    if best_cost == float('inf'):
        for i in range(len(roads)):
            for j in range(i + 1, len(roads)):
                idx1, idx2 = roads[i], roads[j]
                road_id_1 = idx1[3]
                road_id_2 = idx2[3]
                cost = idx1[2] + idx2[2]

                if cost >= best_cost:
                    continue

                if not check_connectivity(s, {road_id_1, road_id_2}):
                    best_cost = cost
                    best_roads = [road_id_1, road_id_2]

    if best_cost == float('inf'):
        return "-1"

    best_roads.sort()
    return f"{best_cost}\n{len(best_roads)}\n{' '.join(map(str, best_roads))}"

