    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Find all connected components using DFS
    visited = [False] * (n + 1)
    components = []

    dfs_stack = []
    for start in range(1, n + 1):
        if not visited[start]:
            stack = [start]
            visited[start] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(size)

    # Generate lucky numbers up to n
    lucky_numbers = set()
    for length in range(1, 7):  # Enough for n up to 10^5
        def generate(current_val, length):
            if length == 0:
                lucky_numbers.add(current_val)
                return
            for digit in [4, 7]:
                length -= 1
                generate(current_val * 10 + digit, length)

        # Actually regenerate with corrected logic
        def gen_lucky(current, remain):
            if remain == 0:
                lucky_numbers.add(current)
                return
            for digit in [4, 7]:
                gen_lucky(current * 10 + digit, remain - 1)

        gen_lucky(0, length)

    # Remove 0 from lucky numbers (need positive)
    lucky_numbers.discard(0)

    # DP to find minimum components to reach each sum
    dp = {}  # sum -> min components needed to reach this sum
    available_sums = {0}

    for comp in components:
        new_sums = []
        for s in available_sums:
            new_sum = s + comp
            if new_sum <= n and new_sum not in dp:
                new_sums.append((new_sum, dp[s] + 1))

        for new_sum, count in new_sums:
            if new_sum not in dp or dp[new_sum] > count:
                dp[new_sum] = count

        available_sums.add(new_sum for new_sum, _ in new_sums)

    # Check if any lucky number is reachable
    min_components = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp:
            min_components = min(min_components, dp[lucky])

    if min_components == float('inf'):
        return "-1\n"

