class FlowGraph:
    def __init__(self, n):
        self.n = n
        self.edges = []
        self.adj = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap):
        forward = [v, cap, len(self.adj[v])]
        backward = [u, 0, len(self.adj[u])]
        self.adj[u].append(forward)
        self.adj[v].append(backward)
        self.edges.append([u, v, cap, 0])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.adj[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.adj[u])):
            ptr[u] = i
            v, cap, rev = self.adj[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
