def Dinic(n_nodes):
    class Edge:
        def __init__(self, to, rev, cap, flow=0):
            self.to = to
            self.rev = rev
            self.cap = cap
            self.flow = flow

    graph = [[] for _ in range(n_nodes)]

    def add_edge(u, v, capacity):
        foward = Edge(v, len(graph[v]), capacity)
        backward = Edge(u, len(graph[u]), 0)
        graph[u].append(foward)
        graph[v].append(backward)

    level = []

    def bfs(s, t):
        nonlocal level
        level = [-1] * n_nodes
        level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for e in graph[u]:
                if e.cap - e.flow > 0 and level[e.to] == -1:
                    level[e.to] = level[u] + 1
                    queue.append(e.to)
        return level[t] != -1

    ptr = []

    def dfs(u, t, flow):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(graph[u])):
            e = graph[u][i]
            if level[e.to] == level[u] + 1 and e.cap - e.flow > 0:
                d = dfs(e.to, t, min(flow, e.cap - e.flow))
                if d > 0:
                    e.flow += d
                    graph[e.to][e.rev].flow -= d
                    return d
            ptr[u] = i + 1
        return 0

    def max_flow(s, t):
        flow = 0
        while bfs(s, t):
            ptr = [0] * n_nodes
            while True:
                pushed = dfs(s, t, float('inf'))
                if pushed == 0:
                    break
                flow += pushed
        return flow

    return max_flow

