    a = list(map(int, lines[1].split()))

    edges = []
    total_edge_weight = 0

    for i in range(2, 2 + m):
        if i < len(lines):
            u, v, w = map(int, lines[i].strip().split())
            edges.append((u - 1, v - 1, w))  # Convert to 0-indexed
            total_edge_weight += w

    if m == 0:
        return "0"

    # Build min-cut network:
    # Source S -> edge nodes (1..m) with capacity = edge weight
    # Vertex nodes (m+1..m+n) -> Sink T with capacity = vertex weight
    # Vertex -> edge nodes with infinite capacity (enforce constraint)
    # Min-cut = total_edge_weight - max_weight_subgraph

    num_nodes = 2 + m + n
    S = 0
