def sift_down(arr, i):
    n = len(arr)
    while True:
        smallest = i
        l, r = 2 * i + 1, 2 * i + 2

        if l < n and arr[l] < arr[smallest]:
            smallest = l
        if r < n and arr[r] < arr[smallest]:
            smallest = r

        if smallest != i:
            arr[i], arr[smallest] = arr[smallest], arr[i]
            i = smallest
        else:
            break


