        h.append(parts[0])
        a.append(parts[1])

    def check(x):
        """Check if target maximum height x is achievable with at most k*m strikes"""
        needed = 0
        for i in range(n):
            # If not hammered, bamboo i would reach h[i] + m*a[i]
            target = h[i] + m * a[i]
            if target > x:
                # Need ceil((target - x)/p) hammer strikes
                surplus = target - x
                if surplus % p == 0:
                    s_i = surplus // p
                else:
                    s_i = surplus // p + 1
                needed += s_i
                if needed > k * m:
                    return False
        return True

    # Binary search for minimum achievable maximum height
    low = 0
    high = 0
    if n > 0:
        high = max(h[i] + m * a[i] for i in range(n))

    if high == 0:
        return "0"

    while low < high:
        mid = (low + high) // 2
        if check(mid):
            high = mid
        else:
            low = mid + 1

    return str(low)

