def compute_result(n, edges):
    """
    Compute the number of ways to assign 0 or 1 to vertices
    such that there exists at least one edge with sum 0, 1, and 2.

    We use inclusion-exclusion counting.
    """

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    total = 1 << n  # Total assignments: 2^n

    # Count assignments with NO edge of a certain type
    # For this, we iterate through all 2^n assignments and check the conditions

    def count_with_no_type0(assignment):
        """
        assignment is a list of length n+1 where assignment[i] is 0 or 1
        Returns True if no edge has sum 0 (i.e., no edge has both endpoints 0)
        """
        for u, v in edges:
            if assignment[u] == 0 and assignment[v] == 0:
                return False  # Has an edge with sum 0
        return True

    def count_with_no_type1(assignment):
        """
        Returns True if no edge has sum 1 (i.e., no edge has exactly one endpoint 0)
        """
        for u, v in edges:
            if assignment[u] ^ assignment[v] == 1:
                return False  # Has an edge with sum 1
        return True

    def count_with_no_type2(assignment):
        """
        Returns True if no edge has sum 2 (i.e., no edge has both endpoints 1)
        """
        for u, v in edges:
            if assignment[u] == 1 and assignment[v] == 1:
                return False  # Has an edge with sum 2
        return True

    count_0 = count_1 = count_2 = 0  # At least one of each edge type present
    count_0c = count_1c = count_2c = 0  # Counterparts for complement

    def has_type0(assignment):
        for u, v in edges:
            if assignment[u] == 0 and assignment[v] == 0:
                return True
        return False

    def has_type1(assignment):
        for u, v in edges:
            if assignment[u] ^ assignment[v] == 1:
                return True
        return False

    def has_type2(assignment):
        for u, v in edges:
            if assignment[u] == 1 and assignment[v] == 1:
                return True
        return False

    for mask in range(1 << n):
        assignment = [(mask >> (n - 1 - i)) & 1 for i in range(n)]
        # Convert to 1-indexed for convenience
        assignment = [0] + assignment

        c0 = has_type0(assignment)
        c1 = has_type1(assignment)
        c2 = has_type2(assignment)

        if c0 and c1 and c2:
            count_0 += 1

    return count_0

