def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    # Case when n=1, k=1
    if n == 1:
        if k == 1:
            return '0'
        return '1\n1'

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]
    edge_list = []

    for i, line in enumerate(lines[1:]):
        if not line.strip():
            break
        parts = line.strip().split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append((v, i + 1))
            adj[v].append((u, i + 1))
            edge_list.append((i + 1, u, v))

    if k == n:
        # No problem roads needed - all in one state
        return '0'

    # BFS to build tree rooted at 1
    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    order = []
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        order.append(u)
        for v, _ in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                queue.append(v)

    # DP: dp[u][s] = min external edges for a subtree of size s rooted at u
    # Actually, we want max internal edges within the k-node state

