class Solution:
    def can_divide(self, n: int, a: int, b: int, p: List[int]) -> Tuple[bool, List[int]]:
        """
        Determines if numbers can be divided into sets A and B.
        Returns (possible, assignment) where assignment[i] is 0 for set A, 1 for set B.
        """
        # Map each number to its index
        num_to_idx = {num: i for i, num in enumerate(p)}

        # Build graph where edges connect numbers that must be in the same set
        # Use Union-Find-style approach with two choices per "component"

        # For each number, determine what it forces
        # x in A requires (a-x) in A, x in B requires (b-x) in B

        # Let's use a constraint satisfaction approach
        # Track which set each connected component must be assigned to

        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
            return px

