        parent = list(range(n))
        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            # Path compression
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        # For each number, if its pair exists, union them
        for x in p:
