            target_b = b - x

            # If a-x exists, it must be same set
            if target_a in num_to_idx:
                target_a_idx = num_to_idx[target_a]
                union(x_idx, target_a_idx)

            # If b-x exists, it must be same set
            if target_b in num_to_idx:
                target_b_idx = num_to_idx[target_b]
                union(x_idx, target_b_idx)

        # Group by connected components
        components = {}
        for i in range(n):
            comp = find(i)
            if comp not in components:
