                valid_assignments.append((tuple(indices), 0))
            else:
                # Must be in B if in A is invalid
                if can_be_in_B(indices):
                    valid_assignments.append((tuple(indices), 1))
                else:
                    # Cannot be in either - impossible
                    return False, []

        # Now we need to check cross-component consistency
        # Build assignment
        assignment = [0] * n
        component_to_set = {}

        for comp, indices in components.items():
            assigned = 0  # Default to A
            possible_A = can_be_in_A(indices)
            possible_B = can_be_in_B(indices)

            if not possible_A and not possible_B:
                return False, []

            if possible_A and not possible_B:
                assigned = 0
            elif not possible_A and possible_B:
                assigned = 1
            else:
                # Both possible, pick A
                assigned = 0

            component_to_set[comp] = assigned
            for idx in indices:
                assignment[idx] = assigned

        # Verify the assignment
        final_result = []
        for i in range(n):
            num = p[i]
