            a, b = map(int, line.strip().split())
            edges.append((a, b))
    return n, edges

def build_adj(edges):
    adj = {}
    for a, b in edges:
        if a not in adj:
            adj[a] = set()
        if b not in adj:
            adj[b] = set()
        adj[a].add(b)
        adj[b].add(a)
    return adj

def count_edges(tree):
    count = 0
    for a, set_b in tree.items():
        for b in set_b:
            count += 2
    return count // 2

def canonical_form(adj):
    components = []
    visited = set()

    def dfs(node, component):
        visited.add(node)
        component.append(node)
        if node in adj:
            for neighbor in sorted(adj[node]):
                if neighbor not in visited:
                    dfs(neighbor, component)

    nodes = sorted(adj.keys())
    for node in nodes:
        if node not in visited:
            component = []
            dfs(node, component)
            components.append(sorted(component))

    return sorted([''.join(map(str, c)) for c in components])

