    """
    Solution for Stablе Matching (Stable Roommates Problem) for cities.
    Each city must pair with exactly one other city.
    A matching is stable if no two unpaired cities would both prefer each other
    over their current matches (cost comparison).
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])

    # Parse cost matrix - build full adjacency matrix
    adj = [[0] * n for _ in range(n)]

