                col_in_row = j if j != i else -1
                if col_in_row == -1:
                    # Find where the diagonal should be
                    adj[i][j] = raw[i][j - 1 if j > i else j]
                    adj[j][i] = raw[j][i - 1 if i > j else i]
                else:
                    adj[i][j] = raw[i][j]
                    adj[j][i] = raw[j][i]

    # Rebuild adjacency properly
    adj = [[0] * n for _ in range(n)]
    for i in range(n):
        r = raw[i]
        for j in range(n):
            if i == j:
                continue
            # Raw row skips the diagonal
            if j < i:
                col = j
            else:
                col = j - 1
            if len(r) - 1 < col:
                continue  # Adjusted
            adj[i][j] = r[col]
            adj[j][i] = raw[j][i - 1 - i if i - 1 - j < len(raw[j]) else j]

    # Create preference lists: each city prefers others with lower connection costs
    prefs = []
    for i in range(n):
        ordered = []
        for j in range(n):
            if i != j:
                ordered.append((adj[i][j], j))
        ordered.sort(key=lambda x: (x[0], x[1]))
        prefs.append([c for c, _ in ordered])

    # Stable Roommates algorithm using priority queue
    matched = [-1] * n
    free = []
    for i in range(n):
        if n % 2 == 1:  # Odd number - impossible to pair all
            return "-1"

    # Track free cities
    free_set = set(range(n))

    # Iterative stable matching
    while free_set:
        # Get city with index 0 for deterministic behavior
        proposer = min(free_set)
        free_set.remove(proposer)
        reordered_prefs = prefs[proposer]

        matched_found = False
        for j in reordered_prefs:
            if j in free_set:
                # Both unmatched - good match
                matched[proposer] = j
                matched[j] = proposer
                free_set.remove(j)
                matched_found = True
                break

            # City j already matched
            current_partner = matched[j]
            if current_partner != -1:
                # Check if both would prefer switching
                cost_pj = adj[proposer][j]
                cost_pc = adj[proposer][current_partner]
                if cost_pj < cost_pc and adj[j][proposer] < adj[j][current_partner]:
                    # Both prefer each other - break current match
                    matched[current_partner] = -1
                    current_partner  # j continues its turn
                    matched[j] = proposer
                    matched[proposer] = j
                    free_set.add(current_partner)
                    free_set.add(proposer)
                    matched_found = True
                    break

        if matched_found:
