def solution(query_input):
    """
    Solves the matrix rectangle partitioning problem.

    Args:
        query_input: String containing n, m and the matrix values

    Returns:
        String with the answer formatted as "! {count}\n"
    """
    from io import StringIO

    # Parse input
    input_stream = StringIO(query_input)

    # Read n, m
    line = input_stream.readline().strip().split()
    if not line:
        return ""
    n, m = int(line[0]), int(line[1])

    # Read matrix
    matrix = []
    for _ in range(n):
        matrix.append(list(map(int, input_stream.readline().split())))

    # Get divisors of a number
    def get_divisors(k):
        return [i for i in range(1, k + 1) if k % i == 0]

    div_n = get_divisors(n)
    div_m = get_divisors(m)

    # Check if all rectangles of size r×c when partitioning matrix are pairwise equal
    def check(r, c):
        """
        For an r×c partition to be valid, all rectangles must be equal.
        This means the matrix must have periodicity with period r in rows
        and period c in columns.
        """
        if r > n or c > m:
            return False

        # Check: matrix[i][j] should equal matrix[i % r][j % c] for all i, j
        # This ensures all cells at the same relative position in each r×c block are equal
        for i in range(n):
            for j in range(m):
                if matrix[i][j] != matrix[i % r][j % c]:
                    return False
        return True

    # Count valid pairs
    count = 0
    for r in div_n:
        for c in div_m:
            if check(r, c):
                count += 1

    return f"! {count}\n"


