def solution(input_str):
    lines = input_str.strip().split('\n')
    n, b = map(int, lines[0].split())

    c = []
    d = []
    parent = [0] * (n + 1)

    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        c.append(parts[0])
        d.append(parts[1])
        if i + 1 >= 2:
            parent[i + 1] = parts[2] if len(parts) > 2 else 0

    # Build children adjacency list
    children = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        children[parent[i]].append(i)

    # dp[i][k] = (cost_not_in_chain[k], cost_in_chain[k]), min cost to buy k items in subtree i
    # cost_not_in_chain: parent doesn't have coupon (children can't use their coupons)
    # cost_in_chain: parent has coupon (children can use their coupons if beneficial)

    dp = [[{0: 0}] * 2 for _ in range(n + 1)]

    # Process in topological order (children before parents)
    # Since parent[i] < i for all i >= 2, we can process in reverse order
    for i in range(1, n + 1):
        # Base: item i alone
        # Without chain: can't build coupon chain, so can only skip or buy at full price
        # With chain: can buy at full price or discounted price

        current_not = {0: 0}  # skip
        current_not[1] = c[i] if i > 0 else 0

        current_with = {0: 0}  # skip
        current_with[1] = c[i] - d[i] if i > 0 else 0

        # Combine with children
        # k=0 means no items from children with this option

        # Initialize child keys
        child_not = {}
        child_with = {}

        for j in children[i]:
            for k in dp[j][0]:
                child_not[k] = dp[j][0][k]
            for k in dp[j][1]:
                child_with[k] = dp[j][1][k]

        # Without chain for i: children forced to not be in chain
        new_not = {0: 0}
        # Option: skip i entirely
        for k, val in child_not.items():
            new_not[k] = min(new_not.get(k, float('inf')), val)

        # Option: buy i at full price if we want
        found_full = False
        for k, val in child_not.items():
            if not found_full:
                new_not[k + 1] = min(new_not.get(k + 1, float('inf')), val + c[i])
                found_full = True

        dp[i][0] = new_not

        # With chain: children can choose optimally between chain and non-chain
        new_with = {0: 0}
        found_reported = False
        for k, val in child_with.items():
            if not found_reported:
                new_with[k + 1] = min(new_with.get(k + 1, float('inf')), val + c[i] - d[i])
                found_reported = True

        dp[i][1] = new_with

    # Find maximum k where dp[1][0][k] <= b or dp[1][1][k] <= b
    result = 0
    for k in range(1, n + 1):
        if dp[1][0].get(k, float('inf')) <= b:
            result = k
        elif dp[1][1].get(k, float('inf')) <= b:
            result = k

    return str(result)


