    MOD = 1000000007

    def cross_product(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def on_segment(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def seg_seg_intersect(a, b, c, d):
        """Check if segments ab and cd intersect at an interior point."""
        c1 = cross_product(a, b, c)
        c2 = cross_product(a, b, d)
        c3 = cross_product(c, d, a)
        c4 = cross_product(c, d, b)

        # Proper intersection at interior point
        if (c1 * c2 < 0) and (c3 * c4 < 0):
            return True

        # Endpoint on the other segment
        if c1 == 0 and on_segment(c, a, b):
            return True
        if c2 == 0 and on_segment(d, a, b):
            return True
        if c3 == 0 and on_segment(a, c, d):
            return True
        if c4 == 0 and on_segment(b, c, d):
            return True

        return False

    def is_valid(i, k):
        """Check if diagonal from vertex i to vertex k is inside the polygon."""
        if k == i:
            return False
        if abs(k - i) == 1:
            return True
        if (i + k) % n == n - 1 and k < i:
            return True

        for j in range(n):
            next_j = (j + 1) % n
            if j == i or j == k or j == k - 1 or j == i - 1:
                continue
            if j == i or j == n - 1 or k == i or k == n - 1:
                continue
            if seg_seg_intersect(coords[i], coords[k], coords[j], coords[next_j]):
                return False
        return True

    # dp[i][j] = number of triangulations for the sub-polygon with vertices
    #            from i to j (going clockwise from i)
    dp = [[0] * n for _ in range(n)]

    for gap in range(1, n):
        for i in range(n):
            j = (i + gap) % n

            if gap == 1 or gap == 2:
                dp[i][j] = 1
            else:
