                    k = k % n
                    if k == i or k == j:
                        continue
                    if is_valid(i, k) and is_valid(k, j):
                        dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    result = dp[0][n - 1] if n >= 3 else 1
