from collections import defaultdict
from math import gcd

def solution(problem_input):
    lines = problem_input.strip().split()
    if len(lines) < 3:
        return "-1"
    try:
        maxx, maxy, w = int(lines[0]), int(lines[1]), int(lines[2])
    except:
        return "-1"

    limit = max(maxx, maxy)
    revs = [0] * (limit + 1)

    for i in range(1, limit + 1):
        revs[i] = int(str(i)[::-1])

    min_prod = float('inf')
    best = None

    # Iterate through all valid (x, y) pairs
    for x in range(1, maxx + 1):
        x_counts = defaultdict(int)
        for a in range(1, x + 1):
            r = revs[a]
            if r == 0:
                continue
            g = gcd(a, r)
            ratio = (a // g, r // g)
            x_counts[ratio] += 1

        current_y_counts = defaultdict(int)
        for y in range(1, maxy + 1):
            # Update y_counts incrementally
            b = y
            r = revs[b]
            if r == 0:
                continue
            g = gcd(b, r)
            ratio = (b // g, r // g)
            current_y_counts[ratio] += 1

            # Calculate matches for this (x, y)
            total = 0
            for r in x_counts:
                if r in current_y_counts:
                    total += x_counts[r] * current_y_counts[r]

            if total >= w:
                prod = x * y
                if prod < min_prod:
                    min_prod = prod
                    best = (x, y)

    if best:
        return f"{best[0]} {best[1]}\n"
    return "-1"
